impl TryFrom<std::sync::Arc<str>> for AdmissionTier {
    type Error = anyhow::Error;

    fn try_from(s: std::sync::Arc<str>) -> Result<Self, Self::Error> {
        <Self as std::str::FromStr>::from_str(s.as_ref())
    }
}

