#[allow(dead_code)]
pub fn per_axis_admission_tier_ceiling(
    probe: &ProbeCoverage,
    verification: &VerificationCoverage,
) -> AdmissionTier {
    probe.admission_tier().join(verification.admission_tier())
}

/// The per-axis-collapse predicate over the per-axis admission-tier
